function shouldRecompute(now, expiry, delta, beta, rnd) {
  return (now - delta * beta * Math.log(rnd)) >= expiry;
}
const expiry = 1000, delta = 0.4, beta = 1.0;
const probes = [
  { now: 999.0, rnd: 0.5 },
  { now: 999.9, rnd: 0.5 },
  { now: 999.9, rnd: 0.95 },
  { now: 999.0, rnd: 0.001 }
];
const out = probes.map(p => String(shouldRecompute(p.now, expiry, delta, beta, p.rnd)));
console.log(out.join(","));
